#Variables about Nigeria and its declaration

country_name = "Nigeria"
capital_city = "Abuja"
continent = "Africa"
president = "Bola Ahmed Tinubu"
independence_year = 1960
currency = "Nigerian Naira (NGN)"

#Brief History on Nigeria
print(f"{country_name} is a country located in West Africa. It has a rich history that dates back to ancient times. The area now known as {country_name} was home to several powerful empires and kingdoms, including the Nok culture, the Kingdom of Benin, and and Yoruba Oyo Empire as well as the sokoto caliphate. The modern nation-state was created by British colonization, with the protectorates of Northern and Southern {country_name} amalgamated in 1914\n")

print(f"In the 19th century, {country_name} became a British colony, and it gained independence in 1960. Since then, {country_name} has experienced a mix of political stability and instability, with periods of military rule and civilian government. The country has also faced various challenges, including economic struggles, corruption, and security issues. A stable democratic government was finally re-established in 1999.\n")

#Ethnic Groups in Nigeria
print(f"{country_name} is a diverse country with over 250 ethnic groups. The three largest ethnic groups are the Hausa, Yoruba, and Igbo, each making up a significant portion of the population.\n")

print(f"The Hausa people are predominantly found in the northern part of {country_name} and are known for their rich cultural heritage, including music, art, and architecture. They are also predominantly Muslim.\n")

print(f"The Yoruba people are primarily located in the southwestern part of {country_name} and have a rich cultural heritage that includes music, art, and religion. They are predominantly Christian, but there is also a significant Muslim population among the Yoruba.\n")

print(f"The Igbo people are mainly found in the southeastern part of {country_name} and are known for their entrepreneurial spirit and rich cultural traditions. They are predominantly Christian, with a small Muslim population.\n")

print(f"In addition to these three major ethnic groups, {country_name} is home to many other smaller ethnic groups, each with their own unique cultures and traditions. The official language is English.\n")

#The Economy of Nigeria
print(f"{country_name} used to be the largest economy in {continent} and is classified as a mixed economy. The country is rich in natural resources, particularly oil and gas, which have been the main drivers of its economy. However, {country_name}'s economy has faced challenges such as corruption, mismanagement, and a heavy reliance on oil exports, which has made it vulnerable to fluctuations in global oil prices.\n")

#The Government & President of Nigeria
print(f"{country_name} operates as a federal republic with a presidential system of government. The President of {country_name} is {president}, who has been in office since {independence_year}.\n")

#Other Information about Nigeria
print(f"The currency of {country_name} is the {currency}. The country has a population of over 200 million people, making it the most populous country in {continent}. The land size of {country_name} is approximately 923,768 square kilometers (356,669 square miles). It ranks 32nd largest country in the world (about twice the size of California) and the capital city is {capital_city}.\n")

#Positives about Nigeria
print(f"{country_name} has a rich cultural heritage, with diverse traditions, languages, and arts. The country is known for its vibrant music and film industries, which have gained international recognition. {country_name} also has a large and growing economy, with a young and dynamic population that contributes to its potential for growth and development.")